    {id:"12-2",type:"qcm",question:"'This morning' in French:",questionFr:"Comment dit-on 'ce matin' ?",options:["Ce matin","Cet matin","Cette matin","Ce matinée"],optionsEn:["This morning","This morning (wrong)","This morning (wrong)","This morning (fem wrong)"],correct:"Ce matin",correctEn:"This morning",explanation:"Ce matin = this morning.",explanationFr:"Ce matin = ce matin."},
