    {id:"12-5",type:"qcm",question:"'This afternoon' in French:",questionFr:"Comment dit-on 'cet après-midi' ?",options:["Cet après-midi","Ce après-midi","Cette après-midi","L'après-midi"],optionsEn:["This afternoon","This afternoon (wrong)","This afternoon (wrong)","The afternoon"],correct:"Cet après-midi",correctEn:"This afternoon",explanation:"Cet because après-midi starts with vowel.",explanationFr:"Cet car après-midi commence par une voyelle."},
